/* Copyright © 2026 上海如静知华信息科技有限公司 · https://www.zhuatech.cn/ */package cn.zhuatech.aieval.model;import jakarta.persistence.*;import java.time.Instant;@Entity@Table(name="evaluation_audit",uniqueConstraints=@UniqueConstraint(name="uk_eval_request",columnNames="request_id"))public class EvaluationAudit{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="request_id",nullable=false,length=80)private String requestId;@Column(nullable=false,length=30)private String decision;@Column(nullable=false)private double score;@Column(nullable=false)private double passRate;@Column(nullable=false,length=500)private String summary;@Column(nullable=false,length=80)private String createdBy;@Column(nullable=false)private Instant createdAt;protected EvaluationAudit(){}public EvaluationAudit(String r,String d,double s,double p,String m,String b){requestId=r;decision=d;score=s;passRate=p;summary=m;createdBy=b;createdAt=Instant.now();}public Long getId(){return id;}public String getRequestId(){return requestId;}public String getDecision(){return decision;}public double getScore(){return score;}public double getPassRate(){return passRate;}public String getSummary(){return summary;}public String getCreatedBy(){return createdBy;}public Instant getCreatedAt(){return createdAt;}}
